function maxHappyGroups(batchSize, groups) {
  const count = new Array(batchSize).fill(0);
  for (const size of groups) {
    count[size % batchSize]++;
  }
  let happy = count[0];
  count[0] = 0;
  for (let r = 1; r <= batchSize - r; r++) {
    const other = batchSize - r;
    const pairs = r === other ? Math.floor(count[r] / 2) : Math.min(count[r], count[other]);
    happy += pairs;
    count[r] -= pairs;
    count[other] -= pairs;
  }

  const memo = new Map();
  const best = (leftover) => {
    const key = count.join(',');
    if (memo.has(key)) return memo.get(key);
    const gain = leftover === 0 ? 1 : 0;
    let result = 0;
    for (let r = 1; r < batchSize; r++) {
      if (count[r] === 0) continue;
      count[r]--;
      result = Math.max(result, gain + best((leftover + r) % batchSize));
      count[r]++;
    }
    memo.set(key, result);
    return result;
  };

  return happy + best(0);
}

