function maxHappyGroups(batchSize, groups) {
  // dp[mask]: most happy groups when exactly the groups in mask are served first, in the best order.
  const n = groups.length;
  const full = (1 << n) - 1;
  const dp = new Array(full + 1).fill(0);
  for (let mask = 0; mask < full; mask++) {
    let served = 0;
    for (let i = 0; i < n; i++) if (mask & (1 << i)) served += groups[i] % batchSize;
    const bonus = served % batchSize === 0 ? 1 : 0;
    for (let i = 0; i < n; i++) {
      if (mask & (1 << i)) continue;
      const next = mask | (1 << i);
      dp[next] = Math.max(dp[next], dp[mask] + bonus);
    }
  }
  return dp[full];
}

