function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const batchSize = int(7, 9);
    // Half the time keep only one side of each complementary pair, which leaves the memoized search the most work.
    const oneSided = rand() < 0.5;
    const groups = [];
    for (let i = 0; i < 30; i++) {
      let r = int(0, batchSize - 1);
      if (oneSided && r > batchSize - r) r = batchSize - r;
      groups.push(r + batchSize * int(r === 0 ? 1 : 0, Math.floor((1000000000 - r) / batchSize)));
    }
    return [batchSize, groups];
  }
  const batchSize = int(1, 9);
  const n = int(1, 7);
  const groups = [];
  for (let i = 0; i < n; i++) groups.push(rand() < 0.15 ? int(999999990, 1000000000) : int(1, 2 * batchSize));
  return [batchSize, groups];
}
